from pathlib import Path
import json
w=Path('/tmp/kuna-rust-array-decay');f=w/'native';f.mkdir(exist_ok=False)
types=[(f'{s}{n*8}',('int'if s=='i'else'uint')+str(n*8)+'_t',('int'if s=='i'else'uint')+str(n),f'{s}{n*8}')for n in [1,2,4,8]for s in ['i','u']]+[('float32','float','float4','f32'),('float64','double','float8','f64'),('pointers','uint8_t*','uint1*','*mut u8'),('flags','_Bool','bool','bool')]
c=['#include <stdint.h>','#define N __attribute__((noinline))','struct DecayFields {uint64_t before;'+''.join(f'{ct} {tag}[9];'for tag,ct,kt,rt in types)+'uint64_t after;};'];rust='#[repr(C)]struct DecayFields{before:u64,'+''.join(f'{tag}:[{rt};9],'for tag,ct,kt,rt in types)+'after:u64}\n'
helpers=['#include <stdint.h>','struct DecayFields;uint64_t trace=0;','N struct DecayFields*counted_base(struct DecayFields*p){trace=trace*100+1;return p;}'];helpers.insert(1,'#define N __attribute__((noinline))');rusthelpers=['static mut TRACE:u64=0;','unsafe fn counted_base(p:*mut DecayFields)->*mut DecayFields{TRACE=TRACE*100+1;p}'];names=[];decl=[];c_calls=[];rust_calls=[]
for tag,ct,kt,rt in types:
 name='pass_value_'+tag;index=next(i for i,x in enumerate(types,1)if x[0]==tag);c.append(f'{ct}*{name}({ct}*);');helpers.append(f'N {ct}*{name}({ct}*p){{trace=trace*100+{index};return p;}}');rusthelpers.append(f'unsafe fn {name}(p:*mut {rt})->*mut {rt}{{TRACE=TRACE*100+{index};p}}')
 for kind in ['field','whole','end','erased','retyped','array','stored','passed']:
  name=kind+'_'+tag;names.append(name)
  if kind in ['whole','end']:
   expr='*p'if kind=='whole'else'&(*p)[9]';c.append(f'N {ct}*{name}({ct}(*p)[9]){{return {expr};}}');decl.append(f'prototype {name} {kt}*{name}({kt}(*p)[9])');cexpr=f'{name}(({ct}(*)[9])array)';rexpr=f'{name}(array as *mut [{rt};9])';base_c='array';base_r='array'
  elif kind=='array':
   c.append(f'N {ct}(*{name}(struct DecayFields*p))[9]{{return ({ct}(*)[9])p->{tag};}}');decl.append(f'prototype {name} {kt}(*{name}(struct DecayFields*p))[9]');cexpr=f'{name}(p)';rexpr=cexpr;base_c='p';base_r='p as *mut u8'
  elif kind=='stored':
   c.append(f'N void {name}({ct}**out,struct DecayFields*p){{*out=p->{tag};}}');decl.append(f'prototype {name} void {name}({kt}**out,struct DecayFields*p)');c_calls.append('{struct {uint64_t before;'+ct+'*value;uint64_t after;}slot={UINT64_C(0x123456789abcdef0),0,UINT64_C(0xfedcba9876543210)};'+name+'(&slot.value,p);report("'+name+'",slot.value,p,0,slot.before,slot.after);}')
   rust_calls.append('{let mut slot=Slot::<'+rt+'>{before:0x123456789abcdef0,value:std::ptr::null_mut(),after:0xfedcba9876543210};'+name+'(&raw mut slot.value,p);report("'+name+'",slot.value as *mut(),p as *mut u8,0,slot.before,slot.after);}')
   continue
  else:
   target='void*'if kind=='erased'else'uint8_t*'if kind=='retyped'else ct+'*';ktarget='void*'if kind=='erased'else'uint1*'if kind=='retyped'else kt+'*';expr=('(void*)'if kind=='erased'else'(uint8_t*)'if kind=='retyped'else'')+f'p->{tag}';expr=f'pass_value_{tag}({expr})'if kind=='passed'else expr;c.append(f'N {target}{name}(struct DecayFields*p){{return {expr};}}');decl.append(f'prototype {name} {ktarget}{name}(struct DecayFields*p)');cexpr=f'{name}(p)';rexpr=cexpr;base_c='p';base_r='p as *mut u8'
  c_calls.append(f'{{trace=0;void*result={cexpr};report("{name}",result,{base_c},trace,0,0);}}');rust_calls.append(f'{{TRACE=0;let result={rexpr} as *mut();let trace=TRACE;report("{name}",result,{base_r},trace,0,0);}}')
c+=['struct DecayFields*counted_base(struct DecayFields*);','N int32_t*passed_counted(struct DecayFields*p){return pass_value_i32(counted_base(p)->i32);}'];names+=['passed_counted'];decl+=['prototype passed_counted int4*passed_counted(struct DecayFields*p)'];c_calls+=['{trace=0;void*result=passed_counted(p);report("passed_counted",result,p,trace,0,0);}'];rust_calls+=['{TRACE=0;let result=passed_counted(p)as*mut();let trace=TRACE;report("passed_counted",result,p as*mut u8,trace,0,0);}']
for tag,ct,kt,rt in types:decl.append(f'prototype pass_value_{tag} {kt}*pass_value_{tag}({kt}*p)')
decl.append('prototype counted_base struct DecayFields*counted_base(struct DecayFields*p)');c+=['#ifndef OMIT_MAIN','int main(void){return 0;}','#endif']
(f/'array_decay.c').write_text('\n'.join(c)+'\n');(f/'array_decay_helpers.c').write_text('\n'.join(helpers)+'\n');(f/'array_decay.kuna').write_text('\n'.join(decl)+'\n');(f/'cases.json').write_text(json.dumps(names,indent=2)+'\n')
header='#define _GNU_SOURCE\n#include <stdio.h>\n#include <inttypes.h>\n#include <string.h>\n#include <sys/mman.h>\n#define OMIT_MAIN\n#include "array_decay.c"\nextern uint64_t trace;\nstatic void report(const char*name,void*result,void*base,uint64_t count,uint64_t before,uint64_t after){printf("%s %016" PRIx64 " %" PRIu64 " %016" PRIx64 " %016" PRIx64 "\\n",name,(uint64_t)((uintptr_t)result-(uintptr_t)base),count,before,after);}\n'
main='int main(void){for(int mode=0;mode<2;mode++)for(int position=0;position<2;position++){void*memory=mmap(0,4096,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);if(memory==MAP_FAILED)return 2;memset(memory,0xa5,4096);struct DecayFields*p=(struct DecayFields*)((char*)memory+128*position);void*array=(char*)memory+2048+128*position;if(mode&&mprotect(memory,4096,PROT_NONE))return 3;printf("mode %d base %d\\n",mode,position);\n'+'\n'.join(c_calls)+'\nif(munmap(memory,4096))return 4;}return 0;}\n';(f/'harness.c').write_text(header+main)
rheader='#![allow(dead_code,unused_variables,unused_parens,unused_mut,non_snake_case)]\n'+rust+'\n'.join(rusthelpers)+'\n#[repr(C)]struct Slot<T>{before:u64,value:*mut T,after:u64}\nextern "C"{fn mmap(p:*mut std::ffi::c_void,n:usize,prot:i32,flags:i32,fd:i32,off:isize)->*mut std::ffi::c_void;fn mprotect(p:*mut std::ffi::c_void,n:usize,prot:i32)->i32;fn munmap(p:*mut std::ffi::c_void,n:usize)->i32;}\nfn report(name:&str,result:*mut(),base:*mut u8,count:u64,before:u64,after:u64){println!("{} {:016x} {} {:016x} {:016x}",name,(result as usize).wrapping_sub(base as usize)as u64,count,before,after);}\n/* EMITTED_BODIES */\n'
rmain='fn main(){unsafe{for mode in 0..2{for position in 0..2{let memory=mmap(std::ptr::null_mut(),4096,3,0x22,-1,0);assert_ne!(memory as isize,-1);std::ptr::write_bytes(memory as *mut u8,0xa5,4096);let p=memory.cast::<u8>().add(128*position)as*mut DecayFields;let array=memory.cast::<u8>().add(2048+128*position);if mode!=0{assert_eq!(mprotect(memory,4096,0),0);}println!("mode {} base {}",mode,position);\n'+'\n'.join(rust_calls)+'\nassert_eq!(munmap(memory,4096),0);}}}}\n';(f/'harness.rs').write_text(rheader+rmain)
assert len(names)==97;print('Generated97 complete-body cases;388 comparisons/profile,776 across O0/O2; readable/protected, two base locations.')
